import{_ as e,o as a,a as t,b as i}from"./app.DKoEZOcr.js";const o="/ascendc.github.io/pr/5487/assets/simt_hw.D1KBHQFz.png",l=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI Core SIMT编程","link":"/guide/programming_guide/programming_model/ai_core_simt_programming/ai_core_simt_programming"},{"text":"抽象硬件架构","link":"/guide/programming_guide/programming_model/ai_core_simt_programming/abstract_hardware_architecture"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_core_simt_programming/abstract_hardware_architecture.md","filePath":"guide/programming_guide/programming_model/ai_core_simt_programming/abstract_hardware_architecture.md","lastUpdated":1787050286000}'),m={name:"guide/programming_guide/programming_model/ai_core_simt_programming/abstract_hardware_architecture.md"};function _(g,r,c,n,d,s){return a(),t("div",null,[...r[0]||(r[0]=[i('<div><article class="markdown-body"><h1>抽象硬件架构<span id="ZH-CN_TOPIC_0000002556525479"></span></h1><p>AI Core上的SIMT（Single Instruction Multiple Thread，单指令多线程）编程允许指令对数据进行独立寻址，从而支持线程级并行计算。这种方式特别适用于离散访问和复杂控制逻辑等场景<span data-filter="950">，目前仅支持Ascend 950PR/Ascend 950DT</span>。SIMT编程能够有效简化复杂算子和不规则控制流的开发，缓解包含分支的发散计算并控制程序复杂度，从而提高硬件利用率和能效。</p><p>如<a href="#fig35720259287">图1</a>所示，AI处理器内部有多个Vector Core，每个Vector Core包含计算单元、Shared Memory（位于Unified Buffer（UB））、寄存器，核外的Global Memory是全局内存空间，被所有Vector Core共享。</p><p><strong>图1</strong> SIMT抽象硬件架构图<span id="fig35720259287"></span><br><img src="'+o+'" alt title="SIMT抽象硬件架构图"></p><p>以下是SIMT多线程计算涉及到的硬件资源的说明：</p><ul><li>每个线程拥有独立的寄存器，用于存储局部数据，寄存器的数量受线程块内线程数量影响，线程数量越多，每个线程拥有的寄存器数量越少。</li><li>UB按功能划分为多个区域，其中一部分内存空间作为线程块内所有线程的共享内存（Shared Memory），支持线程块内的线程进行数据交互；一部分作为Data Cache，用于缓存全局内存数据。</li><li>L2 Cache是所有Vector Core共享的高速缓存，位于Global Memory与各Vector Core的Data Cache之间，用于缓存全局内存数据以减少访问延迟。L2 Cache由硬件自动管理，用户无需显式配置。</li><li>SIMT模式中，读取Global Memory上的数据时，通过Data Cache单元完成数据中转，数据流经由Global Memory到Data Cache，再从Data Cache到寄存器。Data Cache是UB中预留的一部分空间，实际大小由用户自主分配。</li></ul><p>若您对上述内容中的线程、线程块等概念不熟悉，建议查阅<a href="thread_architecture.html">线程架构</a>了解更多SIMT线程架构知识；同时，您也可以通过阅读<a href="memory_hierarchy.html">内存层级</a>，了解如何在UB中配置共享内存与Data Cache的空间大小。</p></article></div>',1)])])}const h=e(m,[["render",_]]);export{l as __pageData,h as default};
